expression.value:
@less(
    concat(
        pipeline().parameters.p_year,
        '-',
        replace(pipeline().parameters.p_month, 'month=', ''),
        '-',
        replace(item().name, 'day=', '')
    ),
    formatDateTime(
        addDays(utcNow(), -7),
        'yyyy-MM-dd'
    )
)

